mapper.insert:
INSERT INTO hr_request (
    request_no, request_type, employee_id, target_department_id, approval_department_id, target_position_id,
    applicant_id, source_version_id, payload_json, status, current_node, version_no,
    submitted_at, completed_at, created_at
) VALUES (
    #{requestNo}, #{requestType}, #{employeeId}, #{targetDepartmentId}, #{approvalDepartmentId}, #{targetPositionId},
    #{applicantId}, #{sourceVersionId}, #{payloadJson}, #{status}, #{currentNode}, #{versionNo},
    #{submittedAt}, #{completedAt}, #{createdAt}
)

INSERT INTO leave_request_detail (request_id, leave_type, start_date, end_date, reason)
SELECT id, #{leaveType}, #{startDate}, #{endDate}, #{reason}
FROM hr_request WHERE request_no = #{requestNo}

INSERT INTO transfer_detail (request_id, from_department_id, from_position_id, effective_date, reason)
SELECT id, #{fromDepartmentId}, #{fromPositionId}, #{effectiveDate}, #{reason}
FROM hr_request WHERE request_no = #{requestNo}

mapper.select:
SELECT COUNT(*) FROM hr_request
WHERE employee_id = #{employeeId}
  AND request_type IN ('ONBOARDING', 'TRANSFER', 'OFFBOARDING')
  AND status IN ('DRAFT', 'PENDING_DEPT_APPROVAL', 'PENDING_HR_APPROVAL', 'APPROVED')
  AND employee_change_applied_at IS NULL
AND id <> #{excludeRequestId}

mapper.insert:
INSERT INTO offboarding_detail (request_id, leave_date, handover_person, handover_status, reason)
SELECT id, #{leaveDate}, #{handoverPerson}, #{handoverStatus}, #{reason}
FROM hr_request WHERE request_no = #{requestNo}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM hr_request r
    LEFT JOIN onboarding_detail o ON o.request_id = r.id
    LEFT JOIN transfer_detail t ON t.request_id = r.id
    LEFT JOIN offboarding_detail f ON f.request_id = r.id
    WHERE r.employee_id = #{employeeId}
      AND r.id <> #{requestId}
      AND r.status = 'APPROVED'
      AND r.employee_change_applied_at IS NULL
      AND r.request_type IN ('ONBOARDING', 'TRANSFER', 'OFFBOARDING')
      AND (
            COALESCE(o.hire_date, t.effective_date, f.leave_date) < #{effectiveDate}
            OR (COALESCE(o.hire_date, t.effective_date, f.leave_date) = #{effectiveDate}
                AND r.id < #{requestId})
      )
)

mapper.update:
UPDATE leave_request_detail
SET effective_from = #{effectiveFrom}, effective_to = #{effectiveTo}
WHERE request_id = #{requestId} AND effective_from IS NULL

mapper.select:
SELECT COUNT(*)
FROM leave_request_detail l
JOIN hr_request r ON r.id = l.request_id
WHERE r.employee_id = #{employeeId}
  AND r.status = 'APPROVED'
  AND l.effective_from IS NOT NULL
  AND l.effective_to IS NOT NULL
  AND l.effective_from <= #{today}
  AND l.effective_to >= #{today}
  AND l.request_id <> #{excludeRequestId}
